const has = (target, key) => Object.prototype.hasOwnProperty.call(target, key);
const listOf = (value) => (Array.isArray(value) ? value : [value]);

export function createMachine(config) {
  if (config === null || typeof config !== 'object') throw new TypeError('config must be an object');
  const states = config.states;
  if (states === null || typeof states !== 'object') {
    throw new TypeError('config.states must be an object');
  }
  if (typeof config.initial !== 'string' || !has(states, config.initial)) {
    throw new ReferenceError(`the initial state ${String(config.initial)} is not defined`);
  }

  for (const name of Object.keys(states)) {
    const on = states[name] === null || typeof states[name] !== 'object'
      ? undefined
      : states[name].on;
    if (on === undefined || on === null) continue;
    for (const type of Object.keys(on)) {
      for (const transition of listOf(on[type])) {
        if (transition === null || typeof transition !== 'object') {
          throw new TypeError('a transition must be an object');
        }
        if (typeof transition.target !== 'string' || !has(states, transition.target)) {
          throw new ReferenceError(`the target ${String(transition.target)} is not defined`);
        }
        if (transition.guard !== undefined && typeof transition.guard !== 'function') {
          throw new TypeError('a guard must be a function');
        }
      }
    }
  }

  const machine = {
    state: config.initial,
    log: [],
    send(event) {
      let type;
      if (typeof event === 'string') type = event;
      else if (event !== null && typeof event === 'object' && typeof event.type === 'string') {
        type = event.type;
      } else {
        throw new TypeError('an event must be a string or an object with a string type');
      }
      const payload = typeof event === 'string' ? { type } : event;

      const current = states[machine.state];
      const on = current.on;
      if (on === undefined || on === null || !has(on, type)) return false;

      let chosen = null;
      for (const transition of listOf(on[type])) {
        if (transition.guard === undefined || transition.guard(payload)) {
          chosen = transition;
          break;
        }
      }
      if (chosen === null) return false;

      if (typeof current.onExit === 'string') machine.log.push(current.onExit);
      if (typeof chosen.action === 'string') machine.log.push(chosen.action);
      const target = states[chosen.target];
      if (typeof target.onEntry === 'string') machine.log.push(target.onEntry);
      machine.state = chosen.target;
      return true;
    },
  };

  const first = states[config.initial];
  if (typeof first.onEntry === 'string') machine.log.push(first.onEntry);
  return machine;
}
